const slugify = s => s.toLowerCase().replace(/&/g, 'and').replace(/['’.:!,()+|]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
// Microsoft Store product IDs are 12 characters (e.g. 9P3H4968GRSM for digital titles, 8-prefixed for devices).
const ALPHABET = '0123456789bcdfghjklmnpqrstvwxz'
function storeId(prefix, key, taken) {
  let h = 2166136261
  for (const c of key) h = Math.imul(h ^ c.codePointAt(0), 16777619) >>> 0
  for (let salt = 0; ; salt++) {
    let n = BigInt(h) * 1000003n + BigInt(salt) * 7919n + 12345n, id = prefix + (n % 2n ? 'n' : 'p')
    for (let i = 0; i < 10; i++) { n = (n * 6364136223846793005n + 1442695040888963407n) % (2n ** 63n); id += ALPHABET[Number(n % 30n)] }
    if (!taken.has(id)) { taken.add(id); return id }
  }
}
const countOf = s => { const m = /^([\d.]+)(K?)$/.exec(String(s || '')); return m ? Number(m[1]) * (m[2] ? 1000 : 1) : 0 }

