// ---------------------------------------------------------------- build
const taken = new Set()
const byTitle = new Map()
const COMMON = { kind: 'other', ribbon: null, purchasable: true, available: true, bundle: [], addons: [], includedIn: [], editions: [], addonsIncluded: [], accessibility: [], capabilities: [], subscriptions: [], languageList: ['English'], languages: 1, handheld: 'Not evaluated', shelf: true }
// Fresh arrays per item: relationship lists are filled in after the rows are built.
const common = () => ({ ...COMMON, bundle: [], addons: [], includedIn: [], editions: [], addonsIncluded: [], accessibility: [], capabilities: [], subscriptions: [], languageList: ['English'] })

function gameRow([title, price, listPrice, publisher, developer, genre, release, rating, ratingCount, age, plats, plans, modes, blurb, extra = {}]) {
  const { sale, series, edition, type = 'game', requires, keywords = '', iap = false, addonsIncluded = [] } = extra
  const now = sale ?? price, list = sale !== undefined ? price : listPrice
  const platforms = [...plats].map(c => PLATFORM[c])
  const xs = plats.includes('X')
  const id = storeId('9', title, taken)
  const caps = [
    ...(xs ? ['Optimized for Xbox Series X|S'] : []), ...(xs && new Date(release) >= new Date('2020-11-10') ? ['4K Ultra HD', 'HDR10'] : []),
    ...(xs && /Shooter|Racing|Sports|Fighting/.test(genre) ? ['120 fps'] : xs ? ['60 fps+'] : []), ...(plats.includes('O') && xs ? ['Smart Delivery'] : []),
    ...(plats.includes('A') ? ['Xbox Play Anywhere'] : []),
  ]
  const recent = new Date(release) >= new Date('2025-01-01')
  return { ...common(), id, slug: slugify(title), family: id, title, shortTitle: title.replace(/ \(Xbox Series X\|S\)$/, ''), type, department: type === 'game' ? 'Games' : 'Add-ons',
    productType: type === 'add-on' ? 'dlc' : edition ? 'bundle' : 'game', entitlement: type === 'add-on' ? 'dlc' : edition ? 'bundle' : 'game',
    price: now, listPrice: list && list > now ? list : null, iap, publisher, developer, brand: publisher, genre, genres: [genre], release, rating, ratingCount,
    age: AGE[age][0], ageNote: AGE[age][1], platforms, subscriptions: [...plans].map(c => PLAN[c]), modes: [...modes].map(c => MODES[c]),
    players: modes.includes('m') || modes.includes('c') ? (modes.includes('s') ? '1 player • Online multiplayer' : 'Online multiplayer') : modes.includes('l') ? '1–4 local players' : '1 player',
    capabilities: caps, accessibility: ['Volume controls', ...(recent || /Xbox Game Studios|Bethesda/.test(publisher) ? ['Subtitles', 'Remappable controls', 'Narrated menus'] : ['Subtitles'])],
    languageList: LANGS.slice(0, /Xbox Game Studios|Bethesda|Electronic Arts|Ubisoft|Activision|CAPCOM|SEGA|2K/.test(publisher) ? 9 : 5),
    handheld: plats.includes('P') ? (plats.includes('A') ? 'Optimized' : 'Compatible') : 'Not evaluated',
    description: [blurb, iap ? 'Offers in-app purchases. Internet connection required for online features.' : 'Online features may require an Xbox Game Pass membership (sold separately).'],
    gamesIncluded: type === 'game' ? [title.replace(/ - Vault Edition| Phantom Edition| Premium Edition|: Deluxe Collection/, '')] : [], addonsIncluded,
    series, edition, requiresTitle: requires,
    keywords: `${keywords} ${publisher} ${developer} ${genre} xbox game ${type === 'add-on' ? 'add-on dlc' : 'digital'} ${platforms.join(' ')}`.toLowerCase(),
  }
}
function addonRow([title, price, base, kind, release, blurb, extra = {}]) {
  const parent = byTitle.get(base)
  const id = storeId('9', title, taken)
  const currency = kind === 'currency'
  return { ...common(), id, slug: slugify(title), family: id, title, shortTitle: title, type: 'add-on', department: 'Add-ons',
    productType: currency ? 'currency' : 'dlc', entitlement: currency ? 'consumable' : 'dlc', repeatable: currency, quantity: extra.quantity,
    price, listPrice: null, iap: false, publisher: parent.publisher, developer: parent.developer, brand: parent.publisher, genre: parent.genre, genres: [parent.genre],
    release, rating: currency ? null : parent.rating, ratingCount: currency ? null : String(Math.max(1, Math.round(countOf(parent.ratingCount) / 9000))) + 'K',
    age: parent.age, ageNote: parent.ageNote, platforms: parent.platforms.filter(p => p !== 'Xbox Play Anywhere'), modes: parent.modes, players: parent.players,
    capabilities: [], accessibility: parent.accessibility, languageList: parent.languageList, requires: parent.id,
    description: [blurb, currency ? `Requires ${parent.title}. Consumable currency can be purchased again and is not a standalone game.` : `Requires ${parent.title}, sold separately. This add-on is not a standalone game.`],
    gamesIncluded: [], keywords: `${extra.keywords || ''} ${parent.title} add-on ${currency ? 'currency in-game' : 'dlc expansion'}`.toLowerCase(),
  }
}
function cardRow([title, price, category, blurb, extra = {}]) {
  const id = storeId('c', title, taken)
  const pass = category === 'Game Pass'
  return { ...common(), id, slug: slugify(title), family: id, title, shortTitle: title, type: 'gift-card', department: 'Gift cards & Game Pass', category: pass ? 'Game Pass memberships' : 'Xbox gift cards',
    productType: pass ? 'membership-code' : 'gift-card', entitlement: 'consumable', repeatable: true, quantity: 1,
    price, listPrice: null, iap: false, publisher: 'Microsoft', developer: 'Microsoft', brand: 'Microsoft', genre: pass ? 'Game Pass' : 'Gift cards', genres: [pass ? 'Game Pass' : 'Gift cards'],
    release: '01/01/2025', rating: pass ? '4.6' : '4.8', ratingCount: pass ? '22K' : '35K', age: 'E', ageNote: 'Everyone', platforms: ['Xbox Series X|S', 'Xbox One', 'PC'], modes: [], players: '—',
    description: [blurb, 'Delivered as a 25-character digital code to your Microsoft account email and order history. Redeem at xbox.com/redeem. US only; not refundable.'],
    gamesIncluded: [], keywords: `${extra.keywords || ''} gift card digital code microsoft store`.toLowerCase(),
  }
}
const compatibility = text => [[/Series X\|S/, 'Xbox Series X|S'], [/Xbox One/, 'Xbox One'], [/Windows/, 'PC'], [/Android|iOS|phone|mobile/i, 'Mobile']].filter(([re]) => re.test(text)).map(([, v]) => v)
function hardwareRow([title, price, listPrice, brand, category, rating, ratingCount, color, shape, blurb, specs, extra = {}]) {
  const id = storeId('8', title, taken)
  const isConsole = category === 'Consoles' || category === 'Handheld gaming'
  return { ...common(), id, slug: slugify(title), family: id, title, shortTitle: title, type: 'hardware', department: isConsole ? 'Consoles' : 'Accessories', category,
    productType: isConsole ? 'console' : 'accessory', entitlement: null, catalogType: isConsole ? 'console' : 'accessory', catalogPlatform: 'xbox', accessorySubtype: isConsole ? null : 'physical',
    physical: true, stock: 25, formatLabel: isConsole ? 'Console' : category, shippingLabel: 'Free standard shipping · Arrives in 3–5 business days',
    price, listPrice: listPrice && listPrice > price ? listPrice : null, iap: false, publisher: brand, developer: brand, brand, genre: category, genres: [category],
    release: '09/01/2025', rating, ratingCount, age: '', ageNote: '', platforms: compatibility(specs.Compatibility || (brand === 'ASUS' ? 'Windows 11 PC' : 'Xbox Series X|S')), modes: [], players: '—',
    color, shape, specs, group: extra.group || null, option: extra.option || null,
    description: [blurb, brand === 'Microsoft' ? 'Sold and shipped by Microsoft Store. Free standard shipping and free 60-day returns on eligible items.' : `Designed for Xbox. Sold by Microsoft Store and made by ${brand}.`],
    gamesIncluded: [], keywords: `${brand} ${category} ${color} ${isConsole ? 'console xbox series' : 'accessory'} ${shape} ${Object.values(specs).join(' ')}`.toLowerCase(),
  }
}

const games = GAMES.map(gameRow)
for (const g of games) byTitle.set(g.title, g)
for (const g of games) if (g.requiresTitle) { g.requires = byTitle.get(g.requiresTitle).id; g.description[1] = `Requires ${g.requiresTitle}, sold separately.` }
const addons = ADDONS.map(addonRow)
const cards = CARDS.map(cardRow)
const hardware = HW.map(hardwareRow)

export const SHELF = [...games, ...addons, ...cards, ...hardware]

// Editions of one game list each other; base games list their add-ons.
const seriesMap = new Map()
for (const p of games) if (p.series) seriesMap.set(p.series, [...(seriesMap.get(p.series) || []), p.id])
for (const p of games) if (p.series) p.editions = seriesMap.get(p.series)
for (const a of [...addons, ...games.filter(g => g.requires)]) { const base = SHELF.find(p => p.id === a.requires); if (base && !base.addons.includes(a.id)) base.addons.push(a.id) }
for (const p of SHELF) { delete p.series; delete p.requiresTitle; p.languages = p.languageList.length }

// Popularity follows rating volume, with a boost for recent releases; ranks start after the GTA VI rows.
const recency = p => { const age = (new Date('2026-10-13') - new Date(p.release)) / 86400000; return age < 0 ? 1.5 : age < 400 ? 2.5 - age / 400 : 1 }
for (const p of SHELF) p.popularity = Math.round((p.productType === 'bundle' ? 0.4 : 1) * (p.type === 'hardware' ? countOf(p.ratingCount) * 1.6 : p.type === 'gift-card' ? countOf(p.ratingCount) : countOf(p.ratingCount) * recency(p)) / 10)
SHELF.sort((a, b) => b.popularity - a.popularity)
SHELF.forEach((p, i) => { p.rank = 20 + i; p.wishlisted = Math.round(p.popularity * (p.type === 'game' ? 1.3 : 0.4)) })
for (const p of SHELF) if (p.listPrice > p.price && p.price !== null) p.discount = `-${Math.round((1 - p.price / p.listPrice) * 100)}%`

// The GTA VI rows have no popularity field in reference mode; these keep popularity sorting meaningful.
